package cn.jingyu.deepseek;
import java.io.*;import java.util.*;import java.util.zip.*;import org.json.*;

/** Output-level regression suite for local publishing and the installed upstream math engine. */
public final class PublishingQualityTest {
 private static int checks;
 private interface Action{void run()throws Exception;}
 private static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);checks++;System.out.println("PASS "+label);}
 private static void near(double actual,double expected,String name){check(Math.abs(actual-expected)<1e-10,name);}
 private static void rejects(Action call,String label)throws Exception{try{call.run();throw new AssertionError(label);}catch(IOException expected){check(true,label);}}
 private static String xml(File file,String entry)throws Exception{try(ZipFile z=new ZipFile(file);InputStream in=z.getInputStream(z.getEntry(entry))){return new String(in.readAllBytes(),"UTF-8");}}
 public static void main(String[] args)throws Exception {
  HostQualityTest.main(args);File out=new File(args[0]);
  near(LocalCalculator.calculate(new JSONObject().put("expression","100/(2*sqrt(100))")).getDouble("value"),5,"upstream engine evaluates nested expression");
  near(LocalCalculator.calculate(new JSONObject().put("expression","-2^2+2^3^2")).getDouble("value"),508,"unary sign and right associative power agree with mathematical convention");
  near(LocalCalculator.calculate(new JSONObject().put("expression","sin(pi/2)+ln(e)+log10(100)")).getDouble("value"),4,"installed engine supports radians constants and logarithms");
  rejects(()->LocalCalculator.calculate(new JSONObject().put("expression","1/0")),"divide by zero cannot become a fabricated document number");
  rejects(()->LocalCalculator.calculate(new JSONObject().put("expression","sqrt(-1)")),"invalid domain is reported");
  rejects(()->LocalCalculator.calculate(new JSONObject().put("expression","Runtime.exec(1)")),"calculator cannot execute program expressions");
  JSONObject stats=LocalCalculator.calculate(new JSONObject().put("values",new JSONArray().put(1).put(2).put(3).put(4)));
  near(stats.getDouble("sum"),10,"statistics sum");near(stats.getDouble("mean"),2.5,"statistics mean");near(stats.getDouble("median"),2.5,"statistics even median");near(stats.getDouble("populationStdDev"),Math.sqrt(1.25),"population standard deviation");near(stats.getDouble("sampleStdDev"),Math.sqrt(5.0/3),"sample standard deviation has correct denominator");
  rejects(()->LocalCalculator.calculate(new JSONObject().put("values",new JSONArray().put("3"))),"statistics do not silently coerce text numbers");
  List<DocumentInline.Run> inline=DocumentInline.parse("**加粗且*斜体***，[链接](https://example.org/a_(b))，`a*b`，$\\frac{1}{s+1}$");boolean nested=false,code=false,math=false,link=false;for(DocumentInline.Run r:inline){nested|=r.bold&&r.italic;code|=r.code&&r.text.equals("a*b");math|=r.math&&r.text.equals("\\frac{1}{s+1}");link|=r.link.equals("https://example.org/a_(b)");}check(nested&&code&&math&&link,"CommonMark preserves nested styling balanced links code and protected math");
  String body="# 学习资料\n\n## 1 参数比较\n\n| 指标 | 数值 | 说明 |\n| :--- | ---: | :---: |\n| 频率 | 12.50 | 保留\\|符号 |\n\n3. 保留原始题号\n4. 下一题\n\n> 提醒：区分自然频率与阻尼振荡频率。\n\n<!-- pagebreak -->\n\n## 2 推导\n\n**重要结论包含*局部强调***。\n\n$$G(s)=\\frac{100}{s^2+14s+100}$$\n\n```c\nint a = 1;\n```\n";
  JSONObject spec=new JSONObject().put("format","docx").put("name","学习资料").put("title","学习资料").put("style","study").put("content",body).put("layout",new JSONObject().put("orientation","landscape").put("fontSize",12).put("subtitle","二阶系统参数与响应").put("pageNumbers",true).put("toc",true));ArtifactSkills.validate(spec);DocumentLayout model=new DocumentLayout(spec);check(model.landscape&&model.bodyWidth>600,"shared model provides a real landscape page");int tables=0;for(DocumentLayout.Block b:model.blocks)if(b.kind.equals("table")){tables++;check(b.rows.get(1)[2].equals("保留|符号")&&b.align[1].equals("right"),"escaped pipes and numeric table alignment survive parsing");}check(tables==1,"one source table becomes one document table");File word=new File(out,"publishing-landscape.docx");try(OutputStream stream=new FileOutputStream(word)){DocxWriter.write(stream,spec);}String w=xml(word,"word/document.xml");check(w.contains("w:orient=\"landscape\"")&&w.contains("w:w=\"16838\""),"Word page is landscape in saved OOXML");check(w.contains("w:anchor=\"section2\"")&&w.contains("w:name=\"section2\""),"Word directory links target actual bookmarks");check(w.contains("<w:footerReference")&&xml(word,"word/footer1.xml").contains("PAGE"),"page numbers use a dynamic Word field");check(w.contains("w:type=\"page\"")&&w.contains("<w:cantSplit/>"),"explicit breaks and short-row keep controls are present");String numbering=xml(word,"word/numbering.xml");check(numbering.contains("w:val=\"3\"")&&numbering.contains("w:val=\"4\""),"original list numbering is retained rather than renumbered");check(w.contains("<w:b/><w:i/>")&&!w.contains("***"),"nested emphasis renders as semantic Word runs");
  JSONObject noNumbers=new JSONObject(spec.toString()).put("layout",new JSONObject().put("pageNumbers",false));File plain=new File(out,"publishing-no-footer.docx");try(OutputStream stream=new FileOutputStream(plain)){DocxWriter.write(stream,noNumbers);}check(!xml(plain,"word/document.xml").contains("footerReference"),"optional page numbers can be disabled");
  rejects(()->ArtifactSkills.validate(new JSONObject().put("format","docx").put("content","```c\nint a;")),"incomplete code is rejected before generating a file card");rejects(()->ArtifactSkills.validate(new JSONObject().put("format","pdf").put("content","$$\\frac{1}{s}")),"unclosed display math is rejected before PDF writing");rejects(()->ArtifactSkills.validate(new JSONObject().put("format","docx").put("content","body").put("layout",new JSONObject().put("fontSize",6))),"unreadably small requested body size is rejected");
  JSONArray rows=new JSONArray().put(new JSONArray().put("项目").put("数值").put("占比").put("编号")).put(new JSONArray().put("A").put(1250.5).put(.25).put("0012")).put(new JSONArray().put("B").put(-20).put(.75).put("=1+2"));
  JSONArray sheets=new JSONArray();for(String type:new String[]{"bar","line"})sheets.put(new JSONObject().put("name","测/试").put("rows",new JSONArray(rows.toString())).put("columnFormats",new JSONArray().put("text").put("number").put("percent").put("text")).put("chart",new JSONObject().put("type",type).put("title","真实数据比较").put("categoryColumn",0).put("valueColumn",1)));
  JSONObject workbook=new JSONObject().put("format","xlsx").put("sheets",sheets);ArtifactSkills.validate(workbook);check(!sheets.getJSONObject(0).getString("name").equals(sheets.getJSONObject(1).getString("name")),"invalid duplicate worksheet names are sanitized and disambiguated");File excel=new File(out,"publishing-multi.xlsx");try(OutputStream stream=new FileOutputStream(excel)){SpreadsheetWriter.write(stream,workbook);}String chart=xml(excel,"xl/charts/chart1.xml"),lineChart=xml(excel,"xl/charts/chart2.xml");check(chart.contains("barChart")&&lineChart.contains("lineChart"),"both native chart types are saved");check(chart.contains("1250.5")&&chart.contains("-20")&&chart.contains("$B$2:$B$3"),"chart caches and references preserve source values including negatives");String sheet=xml(excel,"xl/worksheets/sheet1.xml");check(sheet.contains("0012")&&sheet.contains("=1+2")&&!sheet.contains("<f>"),"identifiers and formula-looking text are not executed or converted");check(xml(excel,"xl/styles.xml").contains("numFmtId=\"10\""),"percent formatting is a native cell number format");check(ArtifactFiles.preview(workbook).contains("0012")&&ArtifactFiles.preview(workbook).contains("测_试 (2)"),"in-app workbook preview includes every worksheet");
  rejects(()->ArtifactSkills.validate(new JSONObject(workbook.toString()).put("format","csv")),"CSV cannot silently lose extra worksheets");JSONObject invalid=new JSONObject(workbook.toString());invalid.getJSONArray("sheets").getJSONObject(0).getJSONArray("rows").getJSONArray(1).put(1,"1250.5");rejects(()->ArtifactSkills.validate(invalid),"chart cannot silently coerce or drop a text data point");
  JSONObject chat=new JSONObject().put("messages",new JSONArray().put(new JSONObject().put("role","user").put("text","计算数据的平均值并生成Excel图表")));check(Conversation.payload(chat,new JSONObject()).optString("tool_choice").equals("auto"),"numeric file tasks allow local calculation before file creation");check(AgentTools.definitions().toString().contains("calculate")&&AgentTools.definitions().toString().contains("sheets"),"model sees the actual installed calculation and multi-sheet tool schema");
  System.out.println("PUBLISHING TOTAL "+checks+" additional checks passed");
 }
}
